\begin{aligned}
G_{t:t+n}\doteq{}&
R_{t+1}+\gamma R_{t+2}+\cdots+\gamma^{n-1}R_{t+n}\\
&+\gamma^n\hat q(S_{t+n},A_{t+n},\mathbf w_{t+n-1}),
\qquad t+n<T.
\end{aligned}

\begin{aligned}
\mathbf w_{t+n}\doteq{}&
\mathbf w_{t+n-1}
+\alpha\bigl[G_{t:t+n}-\hat q(S_t,A_t,\mathbf w_{t+n-1})\bigr]\\
&\quad\cdot\nabla\hat q(S_t,A_t,\mathbf w_{t+n-1}),
\qquad 0\le t<T.
\end{aligned}
